html:
{#- Rendered by wkhtmltopdf (old WebKit): tables only, no flex/float, and no
    Bootstrap class names such as .label that bring their own styling. -#}
{%- set student = frappe.db.get_value("Student", doc.student,
	["student_name", "admission_number", "standard", "current_batch", "group",
	 "father_name", "mother_name", "father_mobile_number", "mother_mobile_number",
	 "preferred_mobile_number"], as_dict=True) or {} -%}
{%- set company = frappe.db.get_default("company") or "BB Academy" -%}
{%- set currency = frappe.db.get_default("currency") or "INR" -%}

{#- The status field is not kept up to date after submit, so work it out here. -#}
{%- if doc.docstatus == 2 -%}
	{%- set bill_status = "Cancelled" -%}
{%- elif doc.docstatus == 0 -%}
	{%- set bill_status = "Draft" -%}
{%- elif (doc.balance_amount or 0) <= 0 -%}
	{%- set bill_status = "Paid" -%}
{%- elif (doc.paid_amount or 0) > 0 -%}
	{%- set bill_status = "Partially Paid" -%}
{%- else -%}
	{%- set bill_status = "Unpaid" -%}
{%- endif -%}

{%- set months = [] -%}
{%- for row in doc.fees_details if row.month and row.month not in months -%}
	{%- set _ = months.append(row.month) -%}
{%- endfor -%}

{%- set phone = student.mother_mobile_number if student.preferred_mobile_number == "Mother"
	else (student.father_mobile_number or student.mother_mobile_number) -%}

{%- macro money(amount) -%}{{ frappe.utils.fmt_money(amount or 0, currency=currency) }}{%- endmacro -%}

<style>
	.bb-bill { font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; color: #222; font-size: 12px; }
	.bb-bill table { width: 100%; border-collapse: collapse; }
	.bb-bill td, .bb-bill th { vertical-align: top; }

	.bb-head td { padding: 0 0 14px; border-bottom: 3px solid #0b4ea2; }
	.bb-brand { font-size: 24px; font-weight: bold; color: #0b4ea2; margin: 0; }
	.bb-sub { color: #666; margin: 2px 0 0; }
	.bb-title { font-size: 20px; font-weight: bold; letter-spacing: 1px; color: #0b4ea2; margin: 0; text-align: right; }
	.bb-meta { text-align: right; margin-top: 6px; line-height: 1.6; }
	.bb-meta-key { color: #666; }

	.bb-badge { display: inline-block; padding: 2px 10px; border-radius: 10px; font-weight: bold; font-size: 11px; }
	.bb-Paid { background: #d4edda; color: #155724; }
	.bb-Partially-Paid { background: #fff3cd; color: #856404; }
	.bb-Unpaid, .bb-Cancelled { background: #f8d7da; color: #721c24; }
	.bb-Draft { background: #e2e3e5; color: #383d41; }

	.bb-section { margin: 18px 0 6px; font-size: 13px; font-weight: bold; color: #0b4ea2; text-transform: uppercase; letter-spacing: .5px; }
	.bb-info td { padding: 4px 6px 4px 0; }
	.bb-key { color: #666; width: 17%; white-space: nowrap; }
	.bb-val { width: 33%; font-weight: bold; }

	.bb-fees th { background: #0b4ea2; color: #fff; padding: 8px; text-align: left; font-weight: bold; }
	.bb-fees td { padding: 8px; border-bottom: 1px solid #e3e6ea; }
	.bb-fees .num { text-align: right; white-space: nowrap; }

	.bb-totals td { padding: 5px 8px; }
	.bb-totals .num { text-align: right; white-space: nowrap; }
	.bb-totals .bb-strong td { font-weight: bold; font-size: 14px; color: #0b4ea2; border-top: 2px solid #0b4ea2; padding-top: 8px; }
	.bb-minus { color: #b02a37; }

	.bb-notes { margin-top: 26px; padding-top: 10px; border-top: 1px solid #e3e6ea; color: #555; font-size: 11px; line-height: 1.6; }
	.bb-foot { margin-top: 18px; text-align: center; color: #999; font-size: 10px; }
</style>

<div class="bb-bill">
	<table class="bb-head">
		<tr>
			<td style="width: 55%;">
				<p class="bb-brand">{{ company }}</p>
				<p class="bb-sub">Tuition Center</p>
			</td>
			<td style="width: 45%;">
				<p class="bb-title">FEE RECEIPT</p>
				<div class="bb-meta">
					<span class="bb-meta-key">Invoice No:</span> <b>{{ doc.name }}</b><br>
					<span class="bb-meta-key">Date:</span> {{ frappe.utils.formatdate(doc.invoice_date) }}<br>
					<span class="bb-badge bb-{{ bill_status | replace(' ', '-') }}">{{ bill_status | upper }}</span>
				</div>
			</td>
		</tr>
	</table>

	<div class="bb-section">Student Details</div>
	<table class="bb-info">
		<tr>
			<td class="bb-key">Name</td><td class="bb-val">{{ student.student_name or doc.student_name or "" }}</td>
			<td class="bb-key">Admission No</td><td class="bb-val">{{ student.admission_number or doc.student }}</td>
		</tr>
		<tr>
			<td class="bb-key">Standard</td><td class="bb-val">{{ student.standard or "-" }}</td>
			<td class="bb-key">Batch</td><td class="bb-val">{{ student.current_batch or "-" }}{% if student.group %} ({{ student.group }}){% endif %}</td>
		</tr>
		<tr>
			<td class="bb-key">Parent</td><td class="bb-val">{{ student.father_name or student.mother_name or "-" }}</td>
			<td class="bb-key">Mobile</td><td class="bb-val">{{ phone or "-" }}</td>
		</tr>
	</table>

	<div class="bb-section">Fee Details</div>
	<table class="bb-fees">
		<thead>
			<tr>
				<th style="width: 6%;">#</th>
				<th>Month</th>
				<th class="num" style="width: 20%;">Fee</th>
				<th class="num" style="width: 18%;">Discount</th>
				<th class="num" style="width: 20%;">Paid</th>
			</tr>
		</thead>
		<tbody>
			{%- for row in doc.fees_details %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ row.month or "-" }}</td>
				<td class="num">{{ money(row.amount_need_to_pay) }}</td>
				<td class="num">{{ money(row.discount_amount) if row.discount_amount else "-" }}</td>
				<td class="num">{{ money(row.paid_amount) }}</td>
			</tr>
			{%- endfor %}
		</tbody>
	</table>

	<table style="margin-top: 12px;">
		<tr>
			<td style="width: 50%; padding-right: 20px; color: #555; line-height: 1.6;">
				{%- if doc.payment_method %}
				<b>Payment Mode:</b> {{ doc.payment_method }}<br>
				{%- if doc.payment_method == "Split Up" %}
					{%- for label, field in [("Cash", "cash"), ("GPay", "gpay"), ("Scanner", "scanner")] if doc.get(field) %}
					{{ label }}: {{ money(doc.get(field)) }}<br>
					{%- endfor %}
				{%- endif %}
				{%- endif %}
				{%- if months %}<b>Month(s):</b> {{ months | join(", ") }}{% endif %}
			</td>
			<td style="width: 50%;">
				<table class="bb-totals">
					<tr><td>Total Fees</td><td class="num">{{ money(doc.monthly_fee) }}</td></tr>
					{%- if doc.add_discount and doc.discount_amount %}
					{%- set discount_reason = doc.discount_reason_remarks if (doc.discount_reason or "").startswith("Others") else doc.discount_reason %}
					<tr><td>Discount{% if discount_reason %} ({{ discount_reason }}){% endif %}</td><td class="num bb-minus">- {{ money(doc.discount_amount) }}</td></tr>
					{%- endif %}
					{%- if doc.apply_gst_18 and doc.gst_amount %}
					<tr><td>GST 18%</td><td class="num">{{ money(doc.gst_amount) }}</td></tr>
					{%- endif %}
					{%- if (doc.grand_total or 0) != (doc.monthly_fee or 0) %}
					<tr><td>Grand Total</td><td class="num">{{ money(doc.grand_total) }}</td></tr>
					{%- endif %}
					{%- if doc.coupon_amount %}
					<tr><td>Coupon{% if doc.coupon__code %} ({{ doc.coupon__code }}){% endif %}</td><td class="num bb-minus">- {{ money(doc.coupon_amount) }}</td></tr>
					{%- endif %}
					<tr class="bb-strong"><td>Amount Paid</td><td class="num">{{ money(doc.paid_amount) }}</td></tr>
					<tr><td>Balance Due</td><td class="num">{{ money(doc.balance_amount) }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	<div class="bb-notes">
		<b>Note:</b><br>
		* Fee once paid is non-refundable under any circumstances.<br>
		* Fee is non-transferable to the next academic year.<br>
		* Fee is non-transferable to another person.
	</div>

	<div class="bb-foot">This is a computer generated receipt and does not require a signature.</div>
</div>
